// Extraer campos del payload de Kaja whatsapp.client_message
const body = $input.first().json.body;

const tenantId = body.tenant_id || 'unknown';
const fromPhone = body.message?.from || body.sender?.phone || '';
const messageText = body.message?.text?.body || body.message?.text || '';
const messageId = body.message?.id || `msg_${Date.now()}`;
const timestamp = new Date().toISOString();

if (!fromPhone || !messageText) {
  throw new Error(`Payload incompleto: from=${fromPhone}, text=${messageText}`);
}

return [{
  json: {
    tenantId,
    fromPhone,
    messageText,
    messageId,
    timestamp,
    sessionKey: `chat_session:${tenantId}:${fromPhone}`,
    contextKey: `booking_context:${tenantId}`
  }
}];

// Combina datos de Branch y Staff, formatea el contexto de negocio
const branch = $('Kaja — GET Branch').item.json;
const staffList = $('Kaja — GET Staff').item.json?.results || [];

const staffSummary = staffList
  .map(s => `- ${s.first_name} ${s.last_name} (${s.specialty || 'Audiología'})`)
  .join('\n');

const context = {
  businessName: branch.name || $env['KAJA_BUSINESS_NAME'],
  address: branch.address || $env['KAJA_BUSINESS_ADDRESS'],
  branchId: branch.id || $env['KAJA_BRANCH_ID'],
  staff: staffList.map(s => ({
    id: s.id,
    name: `${s.first_name} ${s.last_name}`,
    specialty: s.specialty || 'Audiología'
  })),
  contextSummary: `Negocio: ${branch.name}\nDirección: ${branch.address}\nEspecialistas disponibles:\n${staffSummary}`
};

return [{ json: { ...context, contextKey: $('Extraer campos del webhook').item.json.contextKey } }];

// Prepara el contexto (desde caché o recién cargado) para el agente
let context;
try {
  const cached = $('Redis — GET contexto negocio').item.json?.value;
  context = cached ? JSON.parse(cached) : $('Redis — SET contexto (TTL 24h)').item.json;
} catch {
  context = { contextSummary: '' };
}

const extracted = $('Extraer campos del webhook').item.json;

return [{
  json: {
    ...extracted,
    businessContext: context.contextSummary || '',
    businessName: context.businessName || $env['KAJA_BUSINESS_NAME'],
    branchId: context.branchId || $env['KAJA_BRANCH_ID']
  }
}];

// Esta tool registra la urgencia; la escalación real se hace en el nodo Switch posterior
const phone = $execution.customData?.fromPhone || 'desconocido';
const msg = $execution.customData?.messageText || 'mensaje no disponible';
console.log(`[URGENCIA MÉDICA] Paciente: ${phone}, Mensaje: ${msg}`);
return { escalated: true, type: 'DOCTOR', phone, msg };

// Limpia el output del agente: elimina los marcadores internos antes de enviarlo al paciente
const raw = $('AI Agent (Gemini 2.5 Flash)').item.json.output || '';
const clean = raw
  .replace(/\[CAT-[A-Z]+\]/g, '')
  .replace(/\[ESCALAR-[A-Z]+\]/g, '')
  .trim();

const extracted = $('Extraer campos del webhook').item.json;

return [{
  json: {
    agentOutput: raw,
    cleanResponse: clean,
    fromPhone: extracted.fromPhone,
    tenantId: extracted.tenantId,
    timestamp: extracted.timestamp
  }
}];

